CREATE OR REPLACE FUNCTION enforce_timezone_immutability()\nRETURNS trigger AS $$\nBEGIN\n  IF OLD.timezone IS DISTINCT FROM NEW.timezone\n     AND EXISTS (\n       SELECT 1 FROM payment_read_model\n        WHERE project_id = OLD.project_id AND status = 'EXECUTED')\n  THEN\n    RAISE EXCEPTION 'Timezone is immutable after first approved payment (project %)',\n      OLD.project_id;\n  END IF;\n  RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql;\n\nCREATE TRIGGER trg_timezone_immutable\n  BEFORE UPDATE OF timezone ON project\n  FOR EACH ROW EXECUTE FUNCTION enforce_timezone_immutability();\n\n-- Grants globales a app_user (no superuser, no bypassrls)\nGRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA public TO app_user;\nGRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA public TO app_user;\nGRANT EXECUTE ON ALL FUNCTIONS IN SCHEMA public TO app_user;\n\n-- Semilla mínima de calendario (MX_CDMX 2025): lun-vie = business day (DOW 1-5)\nINSERT INTO business_calendar (jurisdiction_id, calendar_date, is_business_day, source)\nSELECT 'MX_CDMX', d::date,\n       EXTRACT(DOW FROM d) BETWEEN 1 AND 5,\n       'SEED'\n  FROM generate_series('2025-01-01'::date, '2025-12-31'::date, '1 day') d\n  ON CONFLICT DO NOTHING;